create table ai_automation_settings (description varchar(255), id varchar(255) not null, mode varchar(255) not null, task varchar(255) not null, threshold varchar(255), primary key (id));
create table anomaly_alerts (amount_impact numeric(15,2), detected_at timestamp(6) with time zone not null, summary varchar(2000), why_flagged varchar(2000), category varchar(255) not null, id varchar(255) not null, linked_entity_id varchar(255), linked_route varchar(255), severity varchar(255) not null, status varchar(255) not null, title varchar(255) not null, evidence json, primary key (id));
create table approval_rules (active boolean not null, condition varchar(1000) not null, approver varchar(255), id varchar(255) not null, name varchar(255) not null, primary key (id));
create table audit_entries (confidence integer, timestamp timestamp(6) with time zone not null, action varchar(1000) not null, reason varchar(2000), approved_by varchar(255), id varchar(255) not null, module varchar(255) not null, outcome varchar(255), primary key (id));
create table bank_reconciliation_items (amount numeric(15,2) not null, statement_date date not null, bank_description varchar(255) not null, id varchar(255) not null, status varchar(255) not null, type varchar(255) not null, ai_suggestion json, primary key (id));
create table catalyst_messages (created_at timestamp(6) with time zone not null, text varchar(4000), id varchar(255) not null, sender varchar(255) not null, sender_label varchar(255), primary key (id));
create table collection_items (days_overdue integer not null, overdue_amount numeric(15,2), promised_amount numeric(38,2), promised_date date, last_contacted timestamp(6) with time zone, draft_message varchar(4000), contact_person varchar(255), customer_id varchar(255) not null, customer_name varchar(255), id varchar(255) not null, phone varchar(255), scheduled_for varchar(255), status varchar(255) not null, tone varchar(255) not null, invoice_refs json, primary key (id));
create table customers (avg_pay_days integer not null, credit_limit numeric(15,2) not null, days_overdue integer not null, outstanding_balance numeric(15,2) not null, last_order_date timestamp(6) with time zone, ai_risk_note varchar(2000), category varchar(255), city varchar(255), contact_person varchar(255), id varchar(255) not null, name varchar(255) not null, phone varchar(255), risk varchar(255), primary key (id));
create table goods_received_notes (received_date date, notes varchar(2000), id varchar(255) not null, linked_invoice_id varchar(255), po_id varchar(255) not null, received_by varchar(255), status varchar(255), supplier_name varchar(255), warehouse varchar(255), primary key (id));
create table inbox_documents (due_date date, invoice_date date, overall_confidence integer not null, photo boolean not null, subtotal numeric(15,2), tax numeric(15,2), total numeric(15,2), received_at timestamp(6) with time zone not null, size_bytes bigint not null, raw_notes varchar(2000), channel varchar(255) not null, content_type varchar(255), doc_type varchar(255), failure_reason varchar(255), file_name varchar(255) not null, id varchar(255) not null, invoice_number varchar(255), sender varchar(255), status varchar(255) not null, stored_path varchar(255) not null, supplier varchar(255), supplier_address varchar(255), supplier_ntn varchar(255), line_items json, three_way_match json, primary key (id));
create table inventory_items (daily_velocity integer not null, reorder_level integer not null, sale_price numeric(15,2), shop_stock integer not null, unit_cost numeric(15,2), van_stock integer not null, warehouse_stock integer not null, category varchar(255), id varchar(255) not null, name varchar(255) not null, preferred_supplier_id varchar(255), preferred_supplier_name varchar(255), sku varchar(255) not null unique, unit varchar(255), primary key (id));
create table ledger_entries (amount numeric(15,2) not null, entry_date date not null, running_balance numeric(15,2) not null, created_at timestamp(6) with time zone not null, category varchar(255), description varchar(255) not null, id varchar(255) not null, party varchar(255), source varchar(255) not null, type varchar(255) not null, primary key (id));
create table payment_records (amount numeric(15,2) not null, cheque_due_date date, payment_date date not null, cheque_bank varchar(255), cheque_number varchar(255), cheque_status varchar(255), customer_name varchar(255) not null, id varchar(255) not null, invoice_ref varchar(255), method varchar(255) not null, reference varchar(255), primary key (id));
create table purchase_orders (created_by_ai boolean not null, expected_date date, total numeric(15,2) not null, created_at timestamp(6) with time zone not null, grn_id varchar(255), id varchar(255) not null, linked_invoice_id varchar(255), status varchar(255) not null, supplier_id varchar(255) not null, supplier_name varchar(255), lines json, primary key (id));
create table sales_orders (ai_confidence integer, total numeric(15,2) not null, created_at timestamp(6) with time zone not null, customer_id varchar(255) not null, customer_name varchar(255), id varchar(255) not null, source varchar(255), status varchar(255) not null, type varchar(255) not null, credit_warning json, items json, original_message json, primary key (id));
create table suppliers (on_time_rate integer not null, ytd_spend numeric(15,2), bank_account_last4 varchar(255), category varchar(255), contact_person varchar(255), id varchar(255) not null, name varchar(255) not null, payment_terms varchar(255), phone varchar(255), tracked_product varchar(255), price_alert json, price_history json, primary key (id));
